import Foundation
import Testing

@testable import OrielOTP

struct EnteSRPClientTests {

    // The vector from Ente's Rust client (rust/crates/accounts/src/auth/srp.rs), whose M1 was generated by
    // Ente's Go server. The private key 0x06de makes A one byte short of the group size, which catches a
    // missing pad when hashing u. B is the server's public key for the private key 0x42 * 64.
    private let identity = "repro-user-id"
    private let salt = Data("0123456789abcdef".utf8)
    private let loginKey = Data("1234567890abcdef".utf8)
    private let privateKey = Data(count: 62) + Data([0x06, 0xde])
    private let serverPublicKey = Data(hex: "")!

    @Test func clientProofMatchesEnteServer() throws {
        let client = EnteSRPClient(identity: identity, password: loginKey, salt: salt, privateKey: privateKey)
        let proofs = try client.proofs(serverPublicKey: serverPublicKey)
        #expect(proofs.clientProof == Data(hex: "c0953b8c74d400fbf664a515deb700d73b65231e7e207a2e2326ff8cf70567ac"))
        #expect(proofs.expectedServerProof == Data(hex: "867014678fa90610b00da7a77c2ede58aae999d612f61580bb3aa199e612a561"))
    }

    @Test func publicKeyIsPaddedToGroupSize() {
        let client = EnteSRPClient(identity: identity, password: loginKey, salt: salt, privateKey: privateKey)
        #expect(client.publicKey.count == 512)
        #expect(client.publicKey.first == 0)
    }

    @Test func randomPrivateKeysGiveDifferentPublicKeys() {
        let first = EnteSRPClient(identity: identity, password: loginKey, salt: salt)
        let second = EnteSRPClient(identity: identity, password: loginKey, salt: salt)
        #expect(first.publicKey != second.publicKey)
    }

    @Test func rejectsInvalidServerValues() {
        let client = EnteSRPClient(identity: identity, password: loginKey, salt: salt, privateKey: privateKey)
        #expect(throws: EnteSRPError.invalidServerValue) { try client.proofs(serverPublicKey: Data(count: 512)) }
        #expect(throws: EnteSRPError.invalidServerValue) { try client.proofs(serverPublicKey: EnteSRPClient.primeBytes) }
        #expect(throws: EnteSRPError.invalidServerValue) { try client.proofs(serverPublicKey: Data(count: 513)) }
    }

    @Test func verifiesServerProof() throws {
        let proof = Data(repeating: 7, count: 32)
        try EnteSRPClient.verify(serverProof: proof, expected: proof)
        var tampered = proof
        tampered[0] ^= 1
        #expect(throws: EnteSRPError.serverProofMismatch) { try EnteSRPClient.verify(serverProof: tampered, expected: proof) }
        #expect(throws: EnteSRPError.serverProofMismatch) { try EnteSRPClient.verify(serverProof: Data(), expected: proof) }
    }
}

extension Data {
    init?(hex: String) {
        guard hex.count.isMultiple(of: 2) else { return nil }
        var bytes = [UInt8]()
        var index = hex.startIndex
        while index < hex.endIndex {
            let next = hex.index(index, offsetBy: 2)
            guard let byte = UInt8(hex[index..<next], radix: 16) else { return nil }
            bytes.append(byte)
            index = next
        }
        self.init(bytes)
    }
}
